  const dx = x1 - x0, dy = y1 - y0;
  const xmin = bx - r, ymin = by - r, xmax = bx + bw + r, ymax = by + bh + r;

  const invx = dx === 0 ? Infinity : 1 / dx;
  const invy = dy === 0 ? Infinity : 1 / dy;

