```js
// Pure: given a travelling ball (prev position → current) and live bricks, find
// the FIRST brick the swept ball overlaps, handling tunnelling. Returns that
// brick and the entry face, or null.
export function sweepBrick(prevX, prevY, ball, bricks) {
  let best = null;       // { brick, face, t }
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const box = {
      left: brick.x - ball.r,
      right: brick.x + brick.w + ball.r,
      top: brick.y - ball.r,
      bottom: brick.y + brick.h + ball.r,
    };
    const hit = segmentEntry(prevX, prevY, ball.x, ball.y, box);
    if (hit && (!best || hit.t < best.t)) {
      best = { brick, face: hit.face, t: hit.t };
    }
  }
  return best;
}
```

